def main():
    cache = {}
    bad = 0
    for c, p, n, anchor, nxt in REFS:
        key = c + ":" + p
        if key not in cache:
            out = subprocess.run(["git", "-C", REPO, "show", key], capture_output=True)
            cache[key] = out.stdout.decode("utf-8").split(chr(10)) if out.returncode == 0 else None
        lines = cache[key]
        ok = lines is not None and len(lines) > n and lines[n - 1].strip().startswith(anchor) and lines[n].strip().startswith(nxt)
        bad += 0 if ok else 1
        print(("ok  " if ok else "BAD ") + c + ":" + p + ":" + str(n))
    print("links %d bad %d" % (len(REFS), bad))
    print("ALL OK" if bad == 0 else "FAILED")
    sys.exit(0 if bad == 0 else 1)
def text(path):
    import re
    body = open(path, encoding="utf-8").read()
    known = {(c, p, n) for c, p, n, _a, _b in REFS}
    found = re.findall(r"`(730ed40a):([A-Za-z0-9_./]+):([0-9]+)`", body)
    miss = 0
    for c, p, n in found:
        full = SHORT.get(p, p)
        if (c, full, int(n)) not in known:
            miss += 1
            print("MISSING " + c + ":" + p + ":" + n)
    print("text links %d missing %d" % (len(found), miss))
    print("ALL OK" if miss == 0 and found else "FAILED")
    sys.exit(0 if miss == 0 and found else 1)
if TEXT:
    text(sys.argv[2])
else:
    main()
